(() => {
  const root = document.documentElement
  const main = document.querySelector('[data-slot="main"]')?.parentElement ?? null
  const left = document.querySelector('[data-slot="sidebar"]')?.parentElement ?? null
  const panel = document.querySelector('[data-dsh-chat-background-right-panel]')
  if (main === null || left === null || panel === null) return false
  const leftWidth = left.getBoundingClientRect().width
  const panelRect = panel.getBoundingClientRect()
  const style = getComputedStyle(panel)
  return root.hasAttribute('data-dsh-chat-background-right-fullscreen') && getComputedStyle(left).visibility === 'visible' && getComputedStyle(main).visibility === 'hidden' && panelRect.left >= leftWidth - 2 && panelRect.right >= window.innerWidth - 2 && panelRect.width >= window.innerWidth - leftWidth - 2 && style.backgroundImage.includes('/chat-backgrounds/files/sample-background.png') && style.backgroundImage.includes('linear-gradient')
})()

(() => {
  const root = document.documentElement
  const main = document.querySelector('[data-slot="main"]')?.parentElement ?? null
  const rightbar = document.querySelector('[data-slot="rightbar"]')
  if (main === null || rightbar === null) return false
  const cell = [...rightbar.querySelectorAll('*')].find((el) => String(el.className).includes('tabCell'))
  const duration = cell === null ? null : getComputedStyle(cell).transitionDuration
  return !root.hasAttribute('data-dsh-chat-background-right-fullscreen') && getComputedStyle(main).visibility === 'visible' && root.hasAttribute('data-dsh-chat-background-no-animation') && (duration === null || duration === '0s')
})()
